// Narrow, validated subset of the protocol generated by the installed Codex CLI.
// See docs/decisions.md. This is a transport client, not an agent harness.
import { z } from 'zod';

export const RpcMessage = z.object({
  id: z.union([z.string(), z.number()]).optional(),
  method: z.string().optional(),
  params: z.record(z.string(), z.unknown()).optional(),
  result: z.unknown().optional(),
  error: z.object({ code: z.number(), message: z.string() }).passthrough().optional(),
});
export const AccountResult = z.object({ account: z.object({ type: z.string() }).passthrough().nullable(), requiresOpenaiAuth: z.boolean() });
export const ThreadResult = z.object({ thread: z.object({ id: z.string() }), approvalPolicy: z.unknown(), sandbox: z.object({ type: z.string(), networkAccess: z.boolean() }), model: z.string() });
export const TurnResult = z.object({ turn: z.object({ id: z.string(), status: z.string() }) });

export type ConnectionStatus = { state: 'disconnected' | 'connecting' | 'auth_required' | 'ready' | 'error'; message: string; runtime?: string; model?: string; verifiedConversation: boolean };
export type ChatEvent = { type: 'progress'; message: string } | { type: 'delta'; text: string; itemId: string } | { type: 'message'; text: string; itemId: string } | { type: 'done'; status: 'completed' | 'failed' | 'interrupted' } | { type: 'error'; code: string; message: string };
